ALTER TABLE public.scholarships ADD COLUMN requisitos_detallados jsonb NOT NULL DEFAULT '[]'::jsonb, ADD COLUMN documentos_requeridos jsonb NOT NULL DEFAULT '[]'::jsonb, ADD COLUMN proceso_postulacion jsonb NOT NULL DEFAULT '[]'::jsonb, ADD COLUMN restricciones jsonb NOT NULL DEFAULT '[]'::jsonb, ADD COLUMN preguntas_frecuentes jsonb NOT NULL DEFAULT '[]'::jsonb, ADD COLUMN fuente_requisitos text, ADD COLUMN ultima_verificacion date, ADD COLUMN estado_datos text NOT NULL DEFAULT 'pendiente_verificacion', ADD COLUMN aviso_datos text; ALTER TABLE public.scholarships ADD CONSTRAINT scholarships_estado_datos_check CHECK (estado_datos IN ('verificada', 'pendiente_verificacion', 'propuesta_ficticia_no_verificada'));